activities.solution:
function razonDeCrecimiento(pasosN, pasos2N) {
  return pasos2N / pasosN;
}

function nombreDeFamilia(pasosN, pasos2N) {
  const razon = razonDeCrecimiento(pasosN, pasos2N);
  if (razon === 1) {
    return "constante";
  }
  if (razon === 2) {
    return "lineal";
  }
  if (razon === 4) {
    return "cuadrático";
  }
  return "otra";
}
